fn initialize_hook(hook: &Path, frontmatter: &HookFrontmatter, body: &str) -> Result<(), MaintainerError> {
    with_hook_lock(hook, || {
        if regular_file_exists(hook)? {
            require_valid(&parse_hook(hook)?)?;
