#[derive(Debug, Clone)]
pub struct TargetContext {
    pub root: PathBuf,
    pub target: PathBuf,
    pub directory: PathBuf,
}
impl TargetContext {
    pub fn new(target: &Path) -> Result<Self, ParseError> {
        if target.file_name().is_some_and(|name| name == HOOK_FILENAME) {
            regular_file_exists(target)?;
        }
        let target = target.canonicalize().map_err(|error| {
            path_error(target, "MH024", format!("could not canonicalize target: {error}"))
        })?;
        let directory = if target.is_file() {
            target.parent().unwrap_or(&target).to_path_buf()
        } else if target.is_dir() {
            target.clone()
        } else {
            return Err(path_error(&target, "MH029", "target is not a regular file or directory"));
        };
        let mut selected = None;
        if let Some(configured) = std::env::var_os("MEMHOOKS_ROOT") {
            let configured = PathBuf::from(configured);
            let root = configured.canonicalize().map_err(|error| {
                path_error(&configured, "MH024", format!("invalid MEMHOOKS_ROOT: {error}"))
            })?;
            if !root.is_dir() {
                return Err(path_error(&root, "MH024", "MEMHOOKS_ROOT must be a directory"));
            }
            if directory.starts_with(&root) {
                selected = Some(root);
            }
        }
        let root = selected.or_else(|| directory.ancestors()
            .find(|dir| dir.join(".git").exists()).map(Path::to_path_buf))
            .or_else(|| directory.ancestors()
                .filter(|dir| std::fs::symlink_metadata(dir.join(HOOK_FILENAME)).is_ok())
                .last().map(Path::to_path_buf))
            .unwrap_or_else(|| directory.clone());
        Ok(Self { root, target, directory })
    }
}

