#[test]
fn library_rejects_invalid_note_inputs_without_mutation() {
    let repo = tempdir().unwrap();
    fs::create_dir(repo.path().join(".git")).unwrap();
    let hook = init(repo.path()).unwrap();
    let before = fs::read(&hook).unwrap();
    let invalid = vec![
        NoteInput { query: "".into(), ..Default::default() },
        NoteInput { query: "bad".into(), priority: Some(f64::NAN), ..Default::default() },
        NoteInput { query: "bad".into(), priority: Some(2.0), ..Default::default() },
        NoteInput { query: "bad".into(), roles: vec![" ".into()], ..Default::default() },
        NoteInput { query: "bad".into(), backends: serde_yaml_ng::from_str("mem0: 42").unwrap(), ..Default::default() },
        NoteInput { query: "bad".into(), entities: serde_yaml_ng::from_str("[{name: '', salience: 2}]").unwrap(), ..Default::default() },
    ];
    for input in invalid {
        assert!(add_note(repo.path(), input).is_err());
        assert_eq!(fs::read(&hook).unwrap(), before);
    }
}

