    let resolved = resolve(&repo.path().join("src")).unwrap();
    assert_eq!(resolved.effective_queries(&[])[0].query, "child");
    assert!(resolved.omitted_queries(&[]).iter().any(|q| q.query == "parent" && q.reason == "inheritance_cut"));
}

